  document.head.appendChild(stile);

  const titolo = document.querySelector('header h1 span:last-child');
  if (titolo) titolo.textContent = 'BASKETBALL PLAYBOOK';
  try { document.title = 'VDM Basketball Playbook'; } catch (e) {}

  /* ---------- si lavora sempre nel Playbook ---------- */
  const tabsOriginale = window.renderTeamTabsUI;
  if (typeof tabsOriginale === 'function'){
    window.renderTeamTabsUI = function(){
      try { activeTeamTab = 'playbook'; singleMatchMode = false; } catch (e) {}
      const r = tabsOriginale.apply(this, arguments);
      document.querySelectorAll('#topmenuViewNav .topmenu-view-btn').forEach(function(b){
        if (b.dataset.view !== 'playbook') b.style.display = 'none';
      });
      try { pulsanteLogo(); } catch (e) {}
      return r;
    };
  }
  // la domanda "dove salvo le clip?" riguarda solo il video
  if (typeof window.chiediCartellaClip === 'function') window.chiediCartellaClip = function(){};

  /* Una lega sola, creata in silenzio: tiene insieme le squadre. L'allenatore
   * vede solo "Squadra" (una per ogni gruppo che allena) e i suoi giochi. */
  function entra(){
    try {
      if (!Array.isArray(DB.leagues)) DB.leagues = [];
      if (!DB.leagues.length) DB.leagues.push({ id: nextId('lg'), name: 'Playbook', sourceUrl: '', teams: [] });
      if (!activeLeagueId || !DB.leagues.some(function(l){ return l.id === activeLeagueId; })) activeLeagueId = DB.leagues[0].id;
      singleMatchMode = false; activeSingleMatchId = null;
      activeTeamTab = 'playbook';
      const sp = document.getElementById('splashScreen');
      if (sp) sp.style.display = 'none';
      renderAll();
    } catch (e) { console.error('edizione playbook:', e); }
  }
  const caricaOriginale = window.caricaLavoroInMemoria;
  if (typeof caricaOriginale === 'function'){
    window.caricaLavoroInMemoria = function(){
      const r = caricaOriginale.apply(this, arguments);
      entra();
      return r;
    };
  }
  /* FUORI DAL COMPUTER (tablet, 22/09): il lavoro sta nella memoria della
   * pagina e il programma lo riprende solo col bottone "Continua sessione
   * precedente" della prima pagina, che qui e' nascosta: riaprendo l'app la
   * squadra appena fatta spariva. Si riprende subito, PRIMA di entra(), che
   * altrimenti crea la lega vuota e il ripristino si tira indietro. */
  if (!(window.VDM && window.VDM.nativo) && typeof caricaOriginale === 'function'){
    /* nell'app iPad il lavoro arriva dal file (window.VDM_LAVORO, messo li'
     * dall'app prima che la pagina parta): si legge quello, non la memoria
     * della pagina, che tiene pochi MB. Va fatto qui, prima di riprendere. */
    if (typeof window.VDM_LAVORO === 'string' && window.VDM_LAVORO && typeof window.readAutosaveSnapshot === 'function'){
      const letturaOriginale = window.readAutosaveSnapshot;
      window.readAutosaveSnapshot = function(){
        try { const o = JSON.parse(window.VDM_LAVORO); if (o && o.db) return o; } catch (e) {}
        return letturaOriginale.apply(this, arguments);
      };
    }
    try { caricaOriginale(); } catch (e) { console.error('edizione playbook, ripresa del lavoro:', e); }
  }
  entra();

  /* ---------- Playbook animato: scritte senza 3D ---------- */
  function scritteSenza3D(){
    const vai = document.getElementById('vdm3dVai');
    function metti(el, testo, titolo){
      if (!el) return;
      if (el.textContent !== testo) el.textContent = testo;
      if (titolo && el.title !== titolo) el.title = titolo;
    }
    metti(document.getElementById('vdm3dVai'), scritta('titolo'), scritta('titolo'));
    metti(document.getElementById('vdm3dAnima'), scritta('anima'), scritta('animaTitolo'));
    metti(document.querySelector('.vdm3d-testa h2'), scritta('titolo'));
    metti(document.querySelector('.vdm3d-spiega'), scritta('spiega'));
    metti(document.querySelector('.vdm3d-vuoto'), scritta('vuoto'));
  }

  /* ---------- foglio schemi: colonne e righe a scelta ----------
   * Una riga = un gioco. Si sceglie quante colonne (2, 3, 4 diagrammi per
   * riga) e quante righe, cioe' quanti giochi, per foglio. Di serie 4 x 4,
   * come nell'app completa. Se un gioco ha piu' fasi disegnate che colonne,
   * va a capo sotto, nella stessa riga-gioco. La scelta si ricorda per
   * squadra. Nell'app completa la stampa resta quella di sempre. */
  const STAMPA_BASE = { c: 4, r: 4 };
  function impostazioniStampa(){
    const team = activeTeam();
    const dove = team || DB;
    const x = dove.pbStampa || {};
    return { c: [2, 3, 4].indexOf(+x.c) >= 0 ? +x.c : STAMPA_BASE.c,
             r: +x.r >= 1 && +x.r <= 8 ? +x.r : STAMPA_BASE.r };
  }
  function salvaStampa(k, v){
    const team = activeTeam();
    const dove = team || DB;
    dove.pbStampa = Object.assign({}, impostazioniStampa(), { [k]: +v });
    try { scheduleAutosave(); } catch (e) {}
  }
  const PAROLE_STAMPA = {
    it: ['Colonne', 'Giochi per foglio'], en: ['Columns', 'Plays per sheet'], es: ['Columnas', 'Jugadas por hoja'],
    fr: ['Colonnes', 'Systèmes par feuille'], pt: ['Colunas', 'Jogadas por folha'], de: ['Spalten', 'Spielzüge pro Blatt'],
    lt: ['Stulpeliai', 'Derinių lape'], pl: ['Kolumny', 'Zagrań na arkusz'], ru: ['Колонки', 'Комбинаций на лист'],
    zh: ['列数', '每页战术数'], ja: ['列', '1枚あたりのプレー'], ko: ['열', '장당 플레이']
  };
  function parolaStampa(i){
    let l = 'en';
    try { if (typeof currentLang !== 'undefined' && currentLang) l = currentLang; } catch (e) {}
    return (PAROLE_STAMPA[l] || PAROLE_STAMPA.en)[i];
  }
  function sceltaStampa(){
    const stampa = document.querySelector('#playbookSection button[onclick="printPlaybookSheet()"]');
    if (!stampa) return;
    let box = document.getElementById('pbSceltaStampa');
    if (!box){
      box = document.createElement('span');
      box.id = 'pbSceltaStampa';
      box.style.cssText = 'display:inline-flex;flex-wrap:wrap;gap:10px;align-items:center;margin-left:10px;font-size:13px;';
      box.innerHTML = '<label><span data-k="0"></span> <select data-campo="c"><option>2</option><option>3</option><option>4</option></select></label>' +
        '<label><span data-k="1"></span> <select data-campo="r">' + [1,2,3,4,5,6,7,8].map(function(n){ return '<option>' + n + '</option>'; }).join('') + '</select></label>';
      box.querySelectorAll('select').forEach(function(sel){
        sel.onchange = function(){ salvaStampa(sel.dataset.campo, sel.value); };
      });
      stampa.insertAdjacentElement('afterend', box);
    }
    const imp = impostazioniStampa();
    box.querySelector('[data-campo="c"]').value = String(imp.c);
    box.querySelector('[data-campo="r"]').value = String(imp.r);
    box.querySelectorAll('[data-k="0"],[data-k="1"]').forEach(function(sp){
      const w = parolaStampa(+sp.dataset.k);
      if (sp.textContent !== w) sp.textContent = w;
    });
    sceltaAvversaria();
  }

  /* L'avversaria del foglio: nome e logo, per squadra. Facoltativa: senza,
   * l'intestazione ha solo la propria squadra. */
  function avversaria(){
    const dove = activeTeam() || DB;
    const x = dove.pbAvversaria || {};
    return { name: x.name || '', logo: x.logo || '' };
  }
  function salvaAvversaria(k, v){
    const dove = activeTeam() || DB;
    dove.pbAvversaria = Object.assign(avversaria(), { [k]: v });
    try { scheduleAutosave(); } catch (e) {}
    renderPlaybookSection();
  }
  const PAROLE_AVV = {
    it: ['Avversaria', 'nome (facoltativo)'], en: ['Opponent', 'name (optional)'], es: ['Rival', 'nombre (opcional)'],
    fr: ['Adversaire', 'nom (facultatif)'], pt: ['Adversário', 'nome (opcional)'], de: ['Gegner', 'Name (optional)'],
    lt: ['Varžovas', 'pavadinimas (nebūtina)'], pl: ['Rywal', 'nazwa (opcjonalnie)'], ru: ['Соперник', 'название (необязательно)'],
    zh: ['对手', '名称（可选）'], ja: ['対戦相手', '名前（任意）'], ko: ['상대', '이름 (선택)']
  };
  function parolaAvv(i){
    let l = 'en';
    try { if (typeof currentLang !== 'undefined' && currentLang) l = currentLang; } catch (e) {}
    return (PAROLE_AVV[l] || PAROLE_AVV.en)[i];
  }
  function sceltaAvversaria(){
    const box = document.getElementById('pbSceltaStampa');
    if (!box) return;
    let a = document.getElementById('pbAvversaria');
    if (!a){
      a = document.createElement('label');
      a.id = 'pbAvversaria';
      a.style.cssText = 'display:inline-flex;gap:6px;align-items:center;';
      a.innerHTML = '<span data-k="avv"></span> <input type="text" maxlength="60" style="width:150px;">' +
        '<button type="button" class="btn small" data-fai="logo"></button>' +
        '<button type="button" class="btn small" data-fai="togli" title="✕">✕</button>' +
        '<input type="file" accept="image/*" style="display:none">';
      const nome = a.querySelector('input[type="text"]');
      const file = a.querySelector('input[type="file"]');
      nome.onchange = function(){ salvaAvversaria('name', nome.value.trim()); };
      a.querySelector('[data-fai="logo"]').onclick = function(ev){ ev.preventDefault(); file.click(); };
      file.onchange = function(){
        const f = file.files && file.files[0];
        if (!f) return;
        const r = new FileReader();
        r.onload = function(){ salvaAvversaria('logo', r.result); };
        r.readAsDataURL(f);
        file.value = '';
      };
      a.querySelector('[data-fai="togli"]').onclick = function(ev){
        ev.preventDefault();
        const dove = activeTeam() || DB;
        delete dove.pbAvversaria;
        try { scheduleAutosave(); } catch (e) {}
        sceltaAvversaria();
      };
      box.appendChild(a);
    }
    const avv = avversaria();
    const nome = a.querySelector('input[type="text"]');
    if (document.activeElement !== nome) nome.value = avv.name;
    nome.placeholder = parolaAvv(1);
    const sp = a.querySelector('[data-k="avv"]');
    if (sp.textContent !== parolaAvv(0)) sp.textContent = parolaAvv(0);
    const bl = a.querySelector('[data-fai="logo"]');
    const html = avv.logo ? '<img src="' + avv.logo + '" alt="" style="width:18px;height:18px;object-fit:contain;background:#fff;border-radius:3px;vertical-align:middle;">' : '🖼';
    if (bl.innerHTML !== html) bl.innerHTML = html;
    a.querySelector('[data-fai="togli"]').style.display = (avv.name || avv.logo) ? '' : 'none';
  }

  // la propria squadra a sinistra, l'avversaria scelta (se c'e') a destra:
  // uguale sul foglio a video e su quello stampato
  function testaFoglio(team){
    const avv = avversaria();
    const ctx = { foglio: 'playbook', teamId: ((team && team.id) || '') + '~pb' };
    const nostra = { badge: team, eyebrow: t('playbook.title'), title: (team && team.name) || '' };
    return avv.name || avv.logo
      ? sheetLetterheadHtml(nostra, t('relazione.vsLabel'), { badge: { name: avv.name, flag: '', logo: avv.logo }, title: avv.name }, ctx)
      : sheetLetterheadHtml(nostra, null, null, ctx);
  }
  // nell'edizione Playbook l'unica intestazione a video e' quella del Playbook
  if (typeof window.printPageHeader === 'function') window.printPageHeader = function(team){ return testaFoglio(team); };

  window.printPlaybookSheet = function(){
    const rows = activePlaybookRows().filter(function(r){ return r.nome || r.slots.some(function(s){ return s.elements && s.elements.length; }); });
    const extra = activePlaybookExtraPage();
    const extraPiena = extra.active && (extra.content || '').trim();
    if (!rows.length && !extraPiena){ toast(t('toast.noSchemesToPrint')); return; }
    const team = activeTeam();
    const imp = impostazioniStampa();
    const C = imp.c, R = imp.r;
    const PIEDE = '<div class="pb-piede"><i></i><span>VDM Basketball Playbook · vdmdata.it</span></div>';
    const logo = team && team.logo ? '<img class="pb-sheet-logo" src="' + team.logo + '" alt="">' : '<div class="pb-sheet-logo-empty"></div>';
    const testa = testaFoglio(team);
    // dove non c'e' un disegno resta spazio bianco, senza campo vuoto
    function cella(slot, nome){
      const pieno = !!(slot && slot.elements && slot.elements.length);
      if (!pieno) return '<div class="print-cell pb-cella-bianca"></div>';
      const src = renderSchemaThumbnail(slot, slot.campoMode || 'half', true);
      return '<div class="print-cell"><img src="' + src + '" data-title="' + escapeHtml(nome || '') +
        '" alt="" onclick="zoomDiagramImage(this.src, this.dataset.title)"></div>';
    }
    function riga(row){
      const nome = row ? row.nome : '';
      const dif = row && row.gruppo === 'difesa';
      const nota = row ? ((row.didascalia || '').trim() || row.slots.map(function(sl){ return (sl.note || '').trim(); }).filter(Boolean).join(' · ')) : '';
            // le caselle restano al loro posto; si tolgono solo quelle vuote in fondo
      let fasi = row ? row.slots.slice() : [];
      while (fasi.length && !(fasi[fasi.length - 1] && fasi[fasi.length - 1].elements && fasi[fasi.length - 1].elements.length)) fasi.pop();
      const righeCampi = Math.max(1, Math.ceil(fasi.length / C));
      const celle = [];
      for (let k = 0; k < righeCampi * C; k++) celle.push(cella(fasi[k] || null, nome));
      // una riga-gioco che va a capo occupa lo spazio di piu' righe: cosi'
      // tutti i campi del foglio hanno la stessa misura
      return '<div class="print-row" style="flex:' + righeCampi + ' 1 0;"><div class="pb-sheet-title">' + logo +
        '<span class="pb-sheet-name">' + (row ? (dif ? '🛡️ ' : '⚡ ') + escapeHtml(nome) : '') + '</span>' +
        (row ? '<span class="pb-sheet-tag">' + escapeHtml(t(dif ? 'print.pbTagDefense' : 'print.pbTagOffense')) + '</span>' : '') +
        '</div><div class="print-row-grid" style="grid-template-columns:repeat(' + C + ',1fr);">' + celle.join('') + '</div>' +
        '<div class="pb-sheet-note pb-dida-stampa" contenteditable="true" spellcheck="false" data-riga="' + escapeHtml(row ? row.id : '') + '">' + escapeHtml(nota) + '</div></div>';
    }
    let pagine = '';
    for (let i = 0; i < rows.length; i += R){
      const qui = rows.slice(i, i + R);
      let html = qui.map(riga).join('');
      // lo spazio che avanza resta bianco (niente campi vuoti), ma conta:
      // i campi hanno la stessa misura anche nell'ultimo foglio
      let usate = qui.reduce(function(n, row){
        let f = row.slots.slice();
        while (f.length && !(f[f.length - 1] && f[f.length - 1].elements && f[f.length - 1].elements.length)) f.pop();
        return n + Math.max(1, Math.ceil(f.length / C));
      }, 0);
      if (usate < R) html += '<div class="pb-spazio-bianco" style="flex:' + (R - usate) + ' 1 0;"></div>';
      pagine += '<div class="print-page pb-print-page">' + testa + '<div class="print-rows-wrap">' + html + '</div>' + PIEDE + '</div>';
    }
    if (extraPiena){
      pagine += '<div class="print-page pb-print-page">' + testa + '<div class="pb-extra-print-body">' +
        escapeHtml(extra.content).replace(/\n/g, '<br>') + '</div></div>';
    }
    openPrintPreview(t('print.playbookTitle'), pagine);
    // la didascalia scritta sul foglio torna nel gioco
    document.querySelectorAll('#printPreviewContent .pb-dida-stampa[data-riga]').forEach(function(el){
      const row = rows.find(function(r){ return r.id === el.dataset.riga; });
      if (!row) return;
      el.addEventListener('input', function(){ row.didascalia = el.textContent; try { scheduleAutosave(); } catch (e) {} });
    });
  };


  /* ---------- logo della squadra ----------
   * Nell'app completa il logo si carica dalla scheda della squadra, che qui
   * non c'e': un pulsante accanto alla squadra, con l'anteprima. Il logo va
   * sull'intestazione del foglio e su ogni riga-gioco. */
  const PAROLA_LOGO = { it: 'Logo', en: 'Logo', es: 'Escudo', fr: 'Logo', pt: 'Emblema', de: 'Logo', lt: 'Logotipas', pl: 'Logo', ru: 'Логотип', zh: '队徽', ja: 'ロゴ', ko: '로고' };
  function pulsanteLogo(){
    const gruppo = document.getElementById('teamSelectGroup');
    if (!gruppo) return;
    let b = document.getElementById('pbLogoBtn');
    if (!b){
      const input = document.createElement('input');
      input.type = 'file'; input.accept = 'image/*'; input.id = 'pbLogoInput'; input.style.display = 'none';
      input.onchange = function(){ if (input.files && input.files[0]) setTeamLogo(input.files[0]); input.value = ''; };
      b = document.createElement('button');
      b.id = 'pbLogoBtn'; b.type = 'button'; b.className = 'btn small';
      b.style.cssText = 'display:inline-flex;align-items:center;gap:6px;';
      b.onclick = function(){ input.click(); };
      gruppo.appendChild(b);
      gruppo.appendChild(input);
    }
    const team = activeTeam();
    b.style.display = team ? 'inline-flex' : 'none';
    let l = 'en';
    try { if (typeof currentLang !== 'undefined' && currentLang) l = currentLang; } catch (e) {}
    const parola = '🖼 ' + (PAROLA_LOGO[l] || PAROLA_LOGO.en);
    const img = team && team.logo ? '<img src="' + team.logo + '" alt="" style="width:20px;height:20px;object-fit:contain;border-radius:3px;background:#fff;">' : '';
    const html = img + '<span>' + parola + '</span>';
    if (b.innerHTML !== html) b.innerHTML = html;
  }


  /* ---------- ordine dei giochi e didascalia, a video ----------
   * Ogni gioco ha ▲ ▼ per spostarlo su o giu': l'ordine e' quello del foglio
   * stampato. Sotto i diagrammi, una riga per la didascalia del gioco. */
  const PAROLE_RIGA = {
    it: ['Sposta su', 'Sposta giù', 'Didascalia del gioco…'], en: ['Move up', 'Move down', 'Caption for this play…'],
    es: ['Subir', 'Bajar', 'Pie de la jugada…'], fr: ['Monter', 'Descendre', 'Légende du système…'],
    pt: ['Subir', 'Descer', 'Legenda da jogada…'], de: ['Nach oben', 'Nach unten', 'Bildunterschrift zum Spielzug…'],
    lt: ['Aukštyn', 'Žemyn', 'Derinio paaiškinimas…'], pl: ['W górę', 'W dół', 'Podpis zagrania…'],
    ru: ['Вверх', 'Вниз', 'Подпись к комбинации…'], zh: ['上移', '下移', '战术说明…'],
    ja: ['上へ', '下へ', 'プレーの説明…'], ko: ['위로', '아래로', '플레이 설명…']
  };
  function parolaRiga(i){
    let l = 'en';
    try { if (typeof currentLang !== 'undefined' && currentLang) l = currentLang; } catch (e) {}
    return (PAROLE_RIGA[l] || PAROLE_RIGA.en)[i];
  }
  function spostaGioco(id, verso){
    const rows = activePlaybookRows();
    const i = rows.findIndex(function(r){ return r.id === id; });
    const j = i + verso;
    if (i < 0 || j < 0 || j >= rows.length) return;
    const x = rows[i]; rows[i] = rows[j]; rows[j] = x;
    try { scheduleAutosave(); } catch (e) {}
    renderPlaybookSection();
  }
  function righeAVideo(){
    const rows = activePlaybookRows();
    document.querySelectorAll('#pbPages .pb-row-filled[data-row-id]').forEach(function(el){
      const id = el.dataset.rowId;
      const row = rows.find(function(r){ return r.id === id; });
      if (!row) return;
      const i = rows.indexOf(row);
      const testa = el.querySelector('.pb-row-head');
      if (testa && !testa.querySelector('.pb-sposta')){
        const del = testa.querySelector('.pb-slot-del');
        // sul tablet si spiega cosa fanno le due frecce
        if (document.body.classList.contains('pb-tablet')){
          const nota = document.createElement('span');
          nota.className = 'pb-ordine-nota';
          let l = 'en';
          try { if (typeof currentLang !== 'undefined' && currentLang) l = currentLang; } catch (e) {}
          nota.textContent = ({ it: 'Ordine del foglio', en: 'Order on the sheet', es: 'Orden en la hoja' })[l] || 'Order on the sheet';
          const del0 = testa.querySelector('.pb-slot-del');
          if (del0) testa.insertBefore(nota, del0); else testa.appendChild(nota);
        }
        [[-1, '▲', 0], [1, '▼', 1]].forEach(function(v){
          const b = document.createElement('button');
          b.type = 'button'; b.className = 'pb-slot-del pb-sposta'; b.textContent = v[1];
          b.title = parolaRiga(v[2]);
          b.dataset.verso = v[0];
          b.onclick = function(ev){ ev.stopPropagation(); spostaGioco(id, v[0]); };
          if (del) testa.insertBefore(b, del); else testa.appendChild(b);
        });
      }
      if (testa){
        const su = testa.querySelector('.pb-sposta[data-verso="-1"]'), giu = testa.querySelector('.pb-sposta[data-verso="1"]');
        if (su) su.disabled = i === 0;
        if (giu) giu.disabled = i === rows.length - 1;
      }
      let dida = el.querySelector('.pb-didascalia');
      if (!dida){
        dida = document.createElement('div');
        dida.className = 'pb-didascalia';
        dida.contentEditable = 'true';
        dida.spellcheck = false;
        dida.textContent = row.didascalia || '';
        dida.oninput = function(){ row.didascalia = dida.textContent; try { scheduleAutosave(); } catch (e) {} };
        dida.onclick = function(ev){ ev.stopPropagation(); };
        const celle = el.querySelector('.pb-row-cells');
        if (celle) celle.insertAdjacentElement('afterend', dida); else el.appendChild(dida);
      }
      if (dida.dataset.ph !== parolaRiga(2)) dida.dataset.ph = parolaRiga(2);
    });
  }


  /* ---------- libreria: tutti i giochi di tutte le squadre ----------
   * L'archivio e' fatto di squadre e, dentro, dei loro giochi. Scrivendo un
   * nome, la casella propone i giochi con quel nome: prima quelli della
   * squadra aperta, poi quelli delle altre (e quelli senza squadra). Scelto
   * un gioco, se ne fa una COPIA in coda alla squadra aperta, con le sue
   * caselle, la didascalia e l'eventuale gioco animato: due ritocchi e il
   * gioco e' pronto. L'originale resta dov'era. */
  const PAROLE_LIB = {
    it: ['📚 Prendi un gioco dall\'archivio…', 'Senza squadra', 'nessun gioco con questo nome', '«{nome}» aggiunto: ritoccalo pure', 'caselle'],
    en: ['📚 Take a play from your archive…', 'No team', 'no play with this name', '«{nome}» added: adjust it as you like', 'boxes'],
    es: ['📚 Toma una jugada del archivo…', 'Sin equipo', 'ninguna jugada con este nombre', '«{nome}» añadida: ajústala como quieras', 'casillas'],
    fr: ['📚 Prendre un système dans l\'archive…', 'Sans équipe', 'aucun système avec ce nom', '«{nome}» ajouté : retouche-le à ton goût', 'cases'],
    pt: ['📚 Pegar uma jogada do arquivo…', 'Sem equipa', 'nenhuma jogada com este nome', '«{nome}» adicionada: ajuste à vontade', 'caixas'],
    de: ['📚 Spielzug aus dem Archiv holen…', 'Ohne Team', 'kein Spielzug mit diesem Namen', '«{nome}» hinzugefügt: jetzt anpassen', 'Felder'],
    lt: ['📚 Paimti derinį iš archyvo…', 'Be komandos', 'derinio tokiu pavadinimu nėra', '«{nome}» pridėtas: pataisykite', 'langeliai'],
    pl: ['📚 Weź zagranie z archiwum…', 'Bez drużyny', 'brak zagrania o tej nazwie', '«{nome}» dodane: popraw je', 'pola'],
    ru: ['📚 Взять комбинацию из архива…', 'Без команды', 'нет комбинации с таким названием', '«{nome}» добавлена: поправьте её', 'клетки'],
    zh: ['📚 从档案中选取战术…', '无球队', '没有这个名字的战术', '已添加「{nome}」：可以修改', '格'],
    ja: ['📚 アーカイブからプレーを選ぶ…', 'チームなし', 'この名前のプレーはありません', '「{nome}」を追加しました：調整してください', '枠'],
    ko: ['📚 보관함에서 플레이 가져오기…', '팀 없음', '이 이름의 플레이가 없습니다', '«{nome}» 추가됨: 다듬어 보세요', '칸']
  };
  function parolaLib(i, valori){
    let l = 'en';
    try { if (typeof currentLang !== 'undefined' && currentLang) l = currentLang; } catch (e) {}
    let w = (PAROLE_LIB[l] || PAROLE_LIB.en)[i];
    Object.keys(valori || {}).forEach(function(k){ w = w.split('{' + k + '}').join(valori[k]); });
    return w;
  }
  function tutteLeSquadre(){
    const elenco = [];
    (DB.leagues || []).forEach(function(l){ (l.teams || []).forEach(function(tm){ if (tm && elenco.indexOf(tm) < 0) elenco.push(tm); }); });
    return elenco;
  }
  function disegnato(row){ return row && (row.slots || []).some(function(sl){ return sl && sl.elements && sl.elements.length; }); }
  function archivio(){
    const aperta = activeTeam();
    const voci = [];
    function metti(squadra, righe, animati){
      (righe || []).forEach(function(row){
        // 23/09: prima l'archivio saltava i giochi SENZA NOME, e chi li aveva
        // disegnati senza battezzarli non li ritrovava piu'. Ora ci sono
        // anche quelli, purche' ci sia almeno un disegno.
        if (!row) return;
        if (!(row.nome || '').trim() && !disegnato(row)) return;
        const anim = (animati || []).find(function(v){ return v && v.origine === row.id; }) || null;
        voci.push({ row: row, squadra: squadra, anim: anim });
      });
    }
    if (aperta) metti(aperta, aperta.playbookRows, aperta.playbook3D);
    tutteLeSquadre().forEach(function(tm){ if (tm !== aperta) metti(tm, tm.playbookRows, tm.playbook3D); });
    metti(null, DB.scratchPlaybookRows, DB.scratchPlaybook3D);
    return voci;
  }
  function norm(x){ return String(x || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim(); }
  function copia(x){ return JSON.parse(JSON.stringify(x)); }
  function prendiDallArchivio(voce){
    const nuova = copia(voce.row);
    nuova.id = nextId('pbrow');
    activePlaybookRows().push(nuova);
    if (voce.anim){
      const team = activeTeam();
      let elenco;
      if (team){ if (!Array.isArray(team.playbook3D)) team.playbook3D = []; elenco = team.playbook3D; }
      else { if (!Array.isArray(DB.scratchPlaybook3D)) DB.scratchPlaybook3D = []; elenco = DB.scratchPlaybook3D; }
      const a = copia(voce.anim);
      a.id = 'pb3d_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      a.origine = nuova.id;
      a.creato = a.modificato = Date.now();
      elenco.push(a);
    }
    try { scheduleAutosave(); } catch (e) {}
    renderPlaybookSection();
    try { toast(parolaLib(3, { nome: nuova.nome })); } catch (e) {}
    setTimeout(function(){
      const el = document.querySelector('#pbPages .pb-row-filled[data-row-id="' + nuova.id + '"]');
      if (el) el.scrollIntoView({ block: 'center', behavior: 'smooth' });
    }, 80);
  }
  function casellaArchivio(){
    const agg = document.querySelector('#playbookSection button[onclick="addPlaybookGame()"]');
    if (!agg) return;
    let box = document.getElementById('pbArchivio');
    if (!box){
      box = document.createElement('span');
      box.id = 'pbArchivio';
      box.style.cssText = 'position:relative;display:inline-block;margin:0 8px;';
      box.innerHTML = '<input type="text" autocomplete="off" spellcheck="false" style="width:260px;">' +
        '<div class="pb-arch-lista" hidden></div>';
      const input = box.querySelector('input');
      const lista = box.querySelector('.pb-arch-lista');
      let trovate = [], scelta = 0;
      function mostra(){
        const q = norm(input.value);
        if (!q){ lista.hidden = true; return; }
        trovate = archivio().filter(function(v){ return norm(v.row.nome).indexOf(q) >= 0; }).slice(0, 30);
        scelta = 0;
        if (!trovate.length){
          lista.innerHTML = '<div class="pb-arch-vuota">' + escapeHtml(parolaLib(2)) + '</div>';
        } else {
          let ultima = undefined;
          lista.innerHTML = trovate.map(function(v, i){
            const sq = v.squadra ? v.squadra.name : parolaLib(1);
            let h = '';
            if (sq !== ultima){ h += '<div class="pb-arch-gruppo">' + escapeHtml(sq) + '</div>'; ultima = sq; }
            const n = (v.row.slots || []).filter(function(sl){ return sl && sl.elements && sl.elements.length; }).length;
            return h + '<div class="pb-arch-voce" data-i="' + i + '">' + (v.row.gruppo === 'difesa' ? '🛡️ ' : '⚡ ') +
              '<b>' + escapeHtml(v.row.nome) + '</b> <span>' + n + ' ' + escapeHtml(parolaLib(4)) + (v.anim ? ' · 🎬' : '') + '</span></div>';
          }).join('');
        }
        lista.hidden = false;
        evidenzia();
      }
      function evidenzia(){
        lista.querySelectorAll('.pb-arch-voce').forEach(function(el){ el.classList.toggle('attiva', +el.dataset.i === scelta); });
      }
      function prendi(i){
        const v = trovate[i];
        if (!v) return;
        input.value = ''; lista.hidden = true;
        prendiDallArchivio(v);
      }
      input.oninput = mostra;
      input.onfocus = mostra;
      input.onkeydown = function(ev){
        if (lista.hidden) return;
        if (ev.key === 'ArrowDown'){ scelta = Math.min(trovate.length - 1, scelta + 1); evidenzia(); ev.preventDefault(); }
        else if (ev.key === 'ArrowUp'){ scelta = Math.max(0, scelta - 1); evidenzia(); ev.preventDefault(); }
        else if (ev.key === 'Enter'){ prendi(scelta); ev.preventDefault(); }
        else if (ev.key === 'Escape'){ lista.hidden = true; }
      };
      lista.onmousedown = function(ev){
        const el = ev.target.closest('.pb-arch-voce');
        if (el){ ev.preventDefault(); prendi(+el.dataset.i); }
      };
      input.onblur = function(){ setTimeout(function(){ lista.hidden = true; }, 150); };
      agg.insertAdjacentElement('afterend', box);
    }
    const input = box.querySelector('input');
    if (input.placeholder !== parolaLib(0)) input.placeholder = parolaLib(0);
  }

  const pbOriginale = window.renderPlaybookSection;
  if (typeof pbOriginale === 'function'){
    window.renderPlaybookSection = function(){
      const r = pbOriginale.apply(this, arguments);
      scritteSenza3D();
      sceltaStampa();
      pulsanteLogo();
      righeAVideo();
      casellaArchivio();
      return r;
    };
  }
  scritteSenza3D();
  sceltaStampa();
  pulsanteLogo();
  casellaArchivio();
  /* il motore riscrive i suoi pulsanti anche fuori da renderPlaybookSection
     (all'avvio, al cambio lingua): si ripassa dopo ogni suo ridisegno */
  const sezPb = document.getElementById('playbookSection');
  if (sezPb){
    let inCorso = false;
    new MutationObserver(function(){
      if (inCorso) return;
      inCorso = true;
      try { scritteSenza3D(); sceltaStampa(); righeAVideo(); casellaArchivio(); } finally { setTimeout(function(){ inCorso = false; }, 0); }
    }).observe(sezPb, { childList: true, subtree: true, characterData: true });
  }



  /* ---------- video dei giochi animati: 10 a disposizione ----------
   * Il Playbook esporta 10 video del gioco animato (2D). Finiti quelli, il
   * gioco si guarda solo a schermo e il pulsante presenta VDM Basketball
   * Coach. Il conto si fa quando il video e' davvero pronto: il motore lo
   * scarica e poi prova a metterlo fra le clip della sezione Video
   * (videoBlobDbSave). Qui la sezione Video non c'e': si conta, si risponde
   * "no" e la clip non viene creata (il file scaricato resta all'utente). */
  const VIDEO_MAX = 10;
  /* TABLET (22/09, Vince: "visto che va su tablet toglierei il blocco per i
   * 2d e 3d"): sull'iPad la completa non c'e', quindi niente limiti: video
   * senza conto e il 3D come nella completa. Si accende solo nella prova per
   * tablet (window.VDM.tablet, messo da strumenti/prepara-tablet.js). */
  const SENZA_LIMITI = !!(window.VDM && window.VDM.tablet);
  if (SENZA_LIMITI) document.body.classList.add('pb-tablet');

  /* NELL'APP iPAD IL LAVORO STA IN UN FILE, non nella memoria della pagina
   * (22/09): quella tiene pochi MB e con i giochi animati, che portano dentro
   * le immagini delle fasi, si riempie e il salvataggio salta. L'app mette il
   * lavoro salvato in window.VDM_LAVORO prima che la pagina parta, e riceve
   * ogni nuovo salvataggio da qui. Nel browser non cambia niente. */
  const PONTE = (function(){
    try { return window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.vdmFile ? window.webkit.messageHandlers.vdmFile : null; } catch (e) { return null; }
  })();
  if (PONTE){
    const CHIAVE = 'vbc_autosave_snapshot_v1';
    let ultimo = typeof window.VDM_LAVORO === 'string' ? window.VDM_LAVORO : null;
    // ogni salvataggio va nel file dell'iPad (e, finche' ci sta, anche dove stava prima)
    const scriviOriginale = Storage.prototype.setItem;
    Storage.prototype.setItem = function(chiave, valore){
      if (chiave === CHIAVE){
        ultimo = String(valore);
        window.VDM_LAVORO = ultimo;
        try { PONTE.postMessage(ultimo); } catch (e) {}
        try { return scriviOriginale.call(this, chiave, valore); } catch (e) { return; }   // se la memoria e' piena, pazienza
      }
      return scriviOriginale.call(this, chiave, valore);
    };
  }

